head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > gotoYear]<br/>Calendar 컴포넌트의 선택 연도를 설정하며 지정한 날짜로 이동합니다.",
    "validation" : [
        "year(필수) 파라미터로 이동할 연도를 Number 또는 String 으로 설정합니다.",
        "'2025', 2025 모두 동일하게 2025년으로 이동합니다.",
        "날짜 이동 후 getValue() 메소드의 반환값이 이동 전과 다르면 onchange 이벤트가 발생합니다.",
        "현재 일자가 이동할 월의 최대 일수를 초과하는 경우 해당 월의 마지막 날짜로 설정됩니다.",
        "gotoYear() 메소드는 minYear/maxYear 속성값의 영향을 받지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        minYear : con_minYear.getValue(),
        maxYear : con_maxYear.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// gotoYear 호출 (선택된 케이스에 따라 분기)
// validation:
//  - year 파라미터를 Number/String 모두 동일 처리
//  - '2025', 2025 모두 동일하게 2025년으로 이동
//  - 현재 일자가 이동할 월의 최대 일수 초과 시 해당 월의 마지막 날짜로 조정 (윤년 2/29 → 평년 2/28)
//  - minYear/maxYear 속성값의 영향을 받지 않음
scwin.btn_gotoYear_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let arg, argDesc;

    // 케이스 3: 일자 보정 검증 사전 셋업 (2024-02-29 윤년 → 2025년 이동 시 평년 2/28 보정)
    if (caseId === '3') {
        target1.gotoCalendar('20240229');
    }

    if (caseId === '1') {
        arg = 2026;
        argDesc = "2026 (Number)";
    } else if (caseId === '2') {
        arg = '2026';
        argDesc = "'2026' (String)";
    } else if (caseId === '3') {
        arg = 2025;
        argDesc = "2025 (Number) / 사전 2024-02-29 → 2025년 이동 시 일자 보정 검증";
    } else if (caseId === '4') {
        arg = 2010;
        argDesc = "2010 (Number) / minYear=2020 미만, 영향 없음 검증";
    } else if (caseId === '5') {
        arg = 2040;
        argDesc = "2040 (Number) / maxYear=2030 초과, 영향 없음 검증";
    }

    let beforeValue = target1.getValue();
    target1.gotoYear(arg);
    let afterValue = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[gotoYear 호출 전 getValue()] '" + beforeValue + "'"
        + " / [gotoYear 인자] " + argDesc
        + " / [gotoYear 호출 후 getValue()] '" + afterValue + "'"
    );
};



// 날짜 이동 후 getValue() 반환값이 이동 전과 다르면 onchange 이벤트 발생
// @spec validation
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생] 선택일이 변경되어 onchange 핸들러 호출됨");
};
